export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "十。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアが開いたとき、光が変わった。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "消えたのではない。赤くなったのだ。蛍光灯は点いたままなのに、光はまるで赤いセロハンを一枚通したようで、鏡も、ボタンも、彼女の手も、すべてを同じ色に染めていた。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアの外は廊下だった。彼女の住む九階とまったく同じ——同じ人造石の床、同じ鉄の扉、同じように並ぶ靴箱。ただ、音がない。エアコンの室外機の音も、遠くのバイクも、どこかの家の冷蔵庫の低い唸りもない。誰かの手で耳をふさがれたような静けさだった。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "廊下の突き当たりの窓の外には、夜景がなかった。むらのない赤が、一面に広がっているだけだった。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）大丈夫。「閉」を押せばいい。", background: Background.Root_Act3_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "閉ボタンを押した。光らない。十二、七、九——どれを押しても、壁を押しているようだった。ドアは開いたままだ。口のように。彼女が自分の足で出ていくのを待っている。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "背後で、あの女は動かなかった。水が床に落ちる。一滴、また一滴。ゆっくりと、時計のように。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "念念？　まだいる？", background: Background.Root_Act3_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "急に電話がクリアになった。不自然なほどはっきりと、方芮の声がすぐ耳元に貼りつく。鼻声だった。泣いていたみたいに。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "なんか言ってよ、お願い。いったいどこにいるの？", background: Background.Root_Act3_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "許念は口を開いた。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女の背後で、誰かが先に口を開いた。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.FifthFloorWoman, character: "五階の女", dialogue: "着いたよ。", background: Background.Root_Act3_S0, portrait: Portrait.FifthFloorWoman_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女の声だった。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "似ているのではない。まったく同じだった。少しかすれていて、語尾が下がる。方芮が「寝不足みたい」と言う、あの声。彼女の背中から半歩のところで聞こえ、うなじの髪が吐息で揺れるほど近かった。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "着いた？　一階？　もう、心臓止まるかと思った……わかった、待ってて。今から迎えに下りるから。", background: Background.Root_Act3_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）わたしじゃない。芮芮、それはわたしじゃない。", background: Background.Root_Act3_S0, portrait: Portrait.XuNian_Scared },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "電話が切れた。ツー、ツー、ツー。そして、その音さえ途絶えた。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "操作盤の上で、数字がまだ読めるボタンは一つだけだった。一。四十年押され続けて、数字はほとんど擦り切れている。赤い光の中で、それは小さな、色あせた出口のように見えた。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）戻りたければ、押せるのは一だけ。それも一回だけ。", background: Background.Root_Act3_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "でも、方芮が言ったのは一階だ。あの声が「着いたよ」と言い、方芮はそれを信じた。今ごろはスリッパのまま階段を下りているのだろう。許念ではない誰かを迎えに。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）一を押して、反応しなかったら？　書いてない。", background: Background.Root_Act3_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はドアの外に並ぶ靴箱を見た。九階の廊下を進めば、三つ目の扉が彼女の家だ。ここが本当にまったく同じなら——", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）だったら、わたしのほうが先に着ける。", background: Background.Root_Act3_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアの外で、廊下が静かに待っている。", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアの内側では、水が一滴ずつ落ちていく。彼女の足もとへ、少しずつ近づきながら。", background: Background.Root_Act3_S0 },
];
